// Resume Scoring Logic - FIXED FOR PDF VECTOR
const candidate = $input.first().json.data;

// Initialize score and breakdown
let score = 0;
let scoreBreakdown = {
  experienceScore: 0,
  educationScore: 0,
  skillsScore: 0
};

// 1. Years of Experience (40 points max)
let totalYearsExperience = 0;
if (candidate.workExperience && candidate.workExperience.length > 0) {
  candidate.workExperience.forEach(exp => {
    const start = new Date(exp.startDate);
    const end = exp.endDate && exp.endDate.toLowerCase() !== 'present' 
      ? new Date(exp.endDate) 
      : new Date();

    if (!isNaN(start.getTime()) && !isNaN(end.getTime())) {
      const years = (end - start) / (1000 * 60 * 60 * 24 * 365);
      totalYearsExperience += years;
    }
  });

  // Score: 0-2 years = 10pts, 2-5 years = 25pts, 5+ years = 40pts
  if (totalYearsExperience >= 5) {
    scoreBreakdown.experienceScore = 40;
  } else if (totalYearsExperience >= 2) {
    scoreBreakdown.experienceScore = 25;
  } else if (totalYearsExperience > 0) {
    scoreBreakdown.experienceScore = 10;
  }
}
score += scoreBreakdown.experienceScore;

// 2. Education Level (30 points max)
if (candidate.education && candidate.education.length > 0) {
  const degrees = candidate.education.map(edu => edu.degree?.toLowerCase() || '');

  if (degrees.some(d => d.includes('phd') || d.includes('doctorate'))) {
    scoreBreakdown.educationScore = 30;
  } else if (degrees.some(d => d.includes('master') || d.includes('mba'))) {
    scoreBreakdown.educationScore = 25;
  } else if (degrees.some(d => d.includes('bachelor') || d.includes('bs') || d.includes('ba'))) {
    scoreBreakdown.educationScore = 20;
  } else {
    scoreBreakdown.educationScore = 10;
  }
}
score += scoreBreakdown.educationScore;

// 3. Skills Match (30 points max)
// Define required skills for the position
const requiredSkills = [
  'javascript', 'python', 'react', 'node', 'nodejs', 
  'sql', 'api', 'git', 'aws', 'docker'
];

let skillsMatched = 0;
// Check technical skills (PDF Vector returns skills.technical)
if (candidate.skills?.technical && candidate.skills.technical.length > 0) {
  const candidateSkills = candidate.skills.technical.map(s => s.toLowerCase());

  requiredSkills.forEach(reqSkill => {
    if (candidateSkills.some(skill => skill.includes(reqSkill))) {
      skillsMatched++;
    }
  });

  // Score: 3 points per matched skill, max 30
  scoreBreakdown.skillsScore = Math.min(skillsMatched * 3, 30);
}
score += scoreBreakdown.skillsScore;

// Calculate final percentage score
const finalScore = Math.round(score);

// Determine status
let status = '';
if (finalScore >= 75) {
  status = 'Strong Candidate - Schedule Interview';
} else if (finalScore >= 50) {
  status = 'Potential - Review Further';
} else {
  status = 'Not a Match';
}

// Format experience for Google Sheets
const experienceText = candidate.workExperience && candidate.workExperience.length > 0
  ? candidate.workExperience.map(exp => `${exp.position} at ${exp.company} (${exp.startDate}-${exp.endDate || 'Present'})`).join('; ')
  : '';

// Format education for Google Sheets
const educationText = candidate.education && candidate.education.length > 0
  ? candidate.education.map(edu => `${edu.degree} from ${edu.institution} (${edu.graduationDate || 'N/A'})`).join('; ')
  : '';

// Format skills for Google Sheets
const skillsText = candidate.skills?.technical && candidate.skills.technical.length > 0
  ? candidate.skills.technical.join(', ')
  : '';

// Get filename from Google Drive Trigger
const fileName = $('Google Drive Trigger1').item.json.name || 'Unknown';

// Return enriched candidate data
return [{
  json: {
    candidate: candidate,
    score: finalScore,
    status: status,
    scoreBreakdown: scoreBreakdown,
    yearsOfExperience: Math.round(totalYearsExperience * 10) / 10,
    skillsMatched: skillsMatched,
    fileName: fileName,
    processedAt: new Date().toISOString(),
    // Formatted for Google Sheets
    experienceFormatted: experienceText,
    educationFormatted: educationText,
    skillsFormatted: skillsText
  }
}];

